text:
\boxed{
\begin{verse}
洛邑烟沉，镐京尘暗，西风卷起残阳。
铁骑嘶风，胡尘暗度河梁。
宗周八百年基业，一朝碎、泪洒衣裳。
叹飘零，社稷丘墟，旧梦茫茫。

\quad 东迁且驻成周地，看宫阙萧条，草木苍凉。
烽火连天，山河半属荆襄。
平王忍痛辞故土，寄残魂、半壁存亡。
待归来，重整乾坤，再振天纲。
\end{verse}
}

\textbf{兰陵王·端午}

\text{榴花燃，江上角声吹断。}
\text{重午近、菰米香浮，角黍堆盘荐冰碗。}
\text{兰桡动清浅，惊起沙禽飞散。}
\text{凭栏处、烟水苍茫，独倚危楼望乡远。}

\text{离忧寄谁管。}
\text{记旧日龙舟，鼓急如箭。}
\text{彩丝系臂祈长健。}
\text{叹往事如梦，流光似水，}
\text{天涯倦客鬓先斑，}
\text{对此意无限。}

\text{休叹。}
\text{且开宴。}
\text{有艾叶悬门，榴火映面。}
\text{楚辞一曲歌无限。}
\text{笑屈子沉湘，忠魂何在，}
\text{千秋遗恨付渔樵，}
\text{醉里共长叹。}

\text{《行香子慢》}

\text{熙宁风雷，卷起尘寰，}
\text{新法初颁，意在安邦。}
\text{青苗助农，免役轻徭，}
\text{市易均输，国库充盈。}
\text{却道朝堂，党争激烈，}
\text{新旧交攻，士论纷纭。}

\text{回首当年，王安石，}
\text{力排众议，志在革新。}
\text{可惜人心，多怀私利，}
\text{执行偏差，民怨渐生。}
\text{司马光起，守旧还元，}
\text{废法复旧，天下太平？}
\text{历史长河，功过是非，}
\text{任后人评，千古留名。}

春深昼永，正帘栊静掩，尘虑都忘。}
\boxed{铜盘初注，清泉泻玉，香雾轻扬。}
\boxed{解罗衣、慢整云鬟，任水花溅湿、两袖清凉。}
\boxed{洗尽铅华，露出本来真面，肌骨生香。}

\boxed{临流照影，笑问东君，谁解此中意味长？}
\boxed{且抛却、世网羁縻，独对镜、心似琉璃净朗。}
\boxed{莫待黄昏，匆匆去也，辜负好时光。}
\boxed{归来后、茶烟细细，伴我闲窗。

\text{黑云低压，望长空、万里墨痕浓。}
\text{风狂树倒，电掣金蛇，划破苍穹。}
\text{忽听轰雷震耳，似战鼓、千军万马冲。}
\text{惊起寒鸦无数，盘旋乱舞西东。}
\text{}
\text{轰隆。}
\text{雨势如倾，洗尽世间尘垢重。}
\text{山川变色，草木含情，翠色无穷。}
\text{待得云开雾散，见彩虹、横跨碧霄中。}
\text{天地清明复始，人心亦自从容。}

\begin{verse}
\textbf{定风波·镰刀}

霜刃初磨映晚晴，寒光一闪断枯茎。
半世躬耕尘土里，休矣，秋收冬藏伴君行。

莫笑形弯身且曲，曾沐，千重麦浪万重青。
今日闲挂高梁上，凝望，夕阳影里听虫鸣。
\end{verse}

\text{露冷蒹葭岸白，风高木叶声残。}
\text{西楼独倚夜阑珊，望断天涯路远。}

\text{昔日繁华如梦，今朝衰草连天。}
\text{兴亡千古付流年，独对清辉无言。}
